function shFnv1a(str, seed){
  var h=(0x811c9dc5 ^ (seed||0))>>>0;
  for(var i=0;i<str.length;i++){
    h=(h^str.charCodeAt(i))>>>0;
    h=(h+((h<<1)+(h<<4)+(h<<7)+(h<<8)+(h<<24)))>>>0;
  }
  return h>>>0;
}
function shFeatures(text){
  var s=String(text).toLowerCase().replace(/[^a-z0-9\u4e00-\u9fff]+/g,' ').trim();
  if(!s) return {};
  var words=s.split(' '), feats={}, i;
  for(i=0;i<words.length;i++) feats[words[i]]=(feats[words[i]]||0)+1;
  for(i=0;i<words.length-1;i++){
    var bg=words[i]+' '+words[i+1];
    feats[bg]=(feats[bg]||0)+1;
  }
  return feats;
}
function shHash64(feat){
  return [shFnv1a(feat, 0x51ed270b), shFnv1a(feat, 0x2545f491)];
}
function simhash64(text){
  var feats=shFeatures(text);
  var v=new Array(64).fill(0), f;
  var any=false;
  for(f in feats){
    any=true;
    var w=feats[f], h=shHash64(f), b;
    for(b=0;b<32;b++) v[b]+=((h[0]>>>b)&1)?w:-w;
    for(b=0;b<32;b++) v[32+b]+=((h[1]>>>b)&1)?w:-w;
  }
  if(!any) return { value:'0000000000000000', error:null };
  var hi=0, lo=0;
  for(var i=0;i<32;i++){ if(v[i]>0) lo=(lo|(1<<i))>>>0; }
  for(var j=0;j<32;j++){ if(v[32+j]>0) hi=(hi|(1<<j))>>>0; }
  var hex=function(x){ var s=x.toString(16); while(s.length<8) s='0'+s; return s; };
  return { value:hex(hi)+hex(lo), error:null };
}
function shPopcount32(x){
  x=x-((x>>>1)&0x55555555);
  x=(x&0x33333333)+((x>>>2)&0x33333333);
  x=(x+(x>>>4))&0x0f0f0f0f;
  return (x*0x01010101)>>>24;
}
function shHamming(hexA, hexB){
  var a=String(hexA).toLowerCase(), b=String(hexB).toLowerCase();
  if(!/^[0-9a-f]{16}$/.test(a)||!/^[0-9a-f]{16}$/.test(b))
    return { value:null, error:'需要 16 位 hex 的 64 位指纹' };
  var d=0;
  for(var i=0;i<16;i+=8){
    var xa=parseInt(a.substr(i,8),16)>>>0, xb=parseInt(b.substr(i,8),16)>>>0;
    d+=shPopcount32((xa^xb)>>>0);
  }
  return { value:d, error:null };
}
function shCompare(textA, textB, threshold){
  var ha=simhash64(textA), hb=simhash64(textB);
  var d=shHamming(ha.value, hb.value);
  if(d.error) return { value:null, error:d.error };
  var t=(typeof threshold==='number')?threshold:3;
  return { value:{ hashA:ha.value, hashB:hb.value, hamming:d.value, nearDup:d.value<=t }, error:null };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { shFnv1a:shFnv1a, shFeatures:shFeatures, simhash64:simhash64,
    shPopcount32:shPopcount32, shHamming:shHamming, shCompare:shCompare };
}
if (typeof window !== 'undefined') {
